class GfG {
    static bool canFinish(int n, int[,] prerequisites) {
        List<List<int>> graph = new List<List<int>>();
        int[] inDegree = new int[n];

        for (int i = 0; i < n; i++)
            graph.Add(new List<int>());

        int m = prerequisites.GetLength(0);
        for (int i = 0; i < m; i++) {
            int dest = prerequisites[i, 0];
            int src = prerequisites[i, 1];
            graph[src].Add(dest);
            inDegree[dest]++;
        }

        Queue<int> q = new Queue<int>();

        // Push all the nodes with no dependencies (indegree = 0)
        for (int i = 0; i < n; i++)
            if (inDegree[i] == 0)
                q.Enqueue(i);

        while (q.Count > 0) {
            int node = q.Dequeue();
            foreach (int child in graph[node]) {
                inDegree[child]--;

                // Push the neighboring node if all dependencies are covered
                if (inDegree[child] == 0)
                    q.Enqueue(child);
            }
        }

        // Check if there is a node whose indegree is not zero
        for (int i = 0; i < n; i++)
            if (inDegree[i] != 0)
                return false;

        return true;
    }

