    while (front < q.length) {
        const node = q[front++];

        for (const child of graph[node]) {
            inDegree[child]--;

            // Push if all dependencies are resolved
            if (inDegree[child] === 0)
                q.push(child);
        }
    }

    // Check if any node still has indegree > 0
    for (let i = 0; i < n; i++)
        if (inDegree[i] !== 0)
            return false;

    return true;
}


